const searchTrainers = `-- name: SearchTrainers :many

SELECT id, display_name, avatar_url, experience_level, trainer_intent, coach_bio, coach_tags
FROM users u
WHERE u.trainer_intent = true
  AND u.id <> $1::text
  AND NOT EXISTS (
    SELECT 1 FROM blocks b
    WHERE (b.blocker_id = $1::text AND b.blocked_id = u.id)
       OR (b.blocker_id = u.id AND b.blocked_id = $1::text)
  )
  AND ($2::text = '' OR u.display_name ILIKE '%' || $2::text || '%')
ORDER BY u.created_at
LIMIT 30
`

type SearchTrainersParams struct {
	ViewerID string
	Query    string
}

type SearchTrainersRow struct {
	ID              string
	DisplayName     *string
	AvatarUrl       *string
	ExperienceLevel *string
	TrainerIntent   bool
	CoachBio        string
	CoachTags       []string
}

// @plm SRS-048  코칭
// 코칭 의향을 밝힌 사람 찾기. **차단한/차단당한 사람과 나 자신은 빼고**.
func (q *Queries) SearchTrainers(ctx context.Context, arg SearchTrainersParams) ([]SearchTrainersRow, error) {
	rows, err := q.db.Query(ctx, searchTrainers, arg.ViewerID, arg.Query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchTrainersRow
	for rows.Next() {
		var i SearchTrainersRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayName,
			&i.AvatarUrl,
			&i.ExperienceLevel,
			&i.TrainerIntent,
			&i.CoachBio,
			&i.CoachTags,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

